for direction in actions:
    if obs['valid_' + direction]:
        score = 0
        for row in range(4):
            cells = [board[row * 4 + column] for column in range(4)] if direction in ('left', 'right') else [board[column * 4 + row] for column in range(4)]
            if direction in ('right', 'down'):
                cells = list(reversed(cells))
            cells = [value for value in cells if value]
            index = 0
            while index + 1 < len(cells):
                if cells[index] == cells[index + 1]:
                    score += cells[index] * 2
                    index += 2
                else:
                    index += 1
        score = score * 2 - actions.index(direction)
        if score > best:
            best = score
            action = direction
